"""Цепочка хэшей журнала аудита поверх живой базы (TZ §4.1 `REQ-identity-04`, §8.7, `T-109`, срез `R1`).

Оффлайновая половинка — `tests/unit/test_audit_chain.py`: там векторы хэшей, каноничность и
разбор цепочки на синтетических строках. Здесь проверяется ровно то, чего память не показывает,
потому что живой `audit_log` — настоящая схема, где:

* **`id` выдаёт база** (`BIGINT GENERATED BY DEFAULT AS IDENTITY`, §4.1): приложение не знает
  его в момент, когда считает хэш, поэтому хэш считается без `id`, а хронологию задаёт именно
  эта колонка — это видно по факту: `ORDER BY id` читается строго в порядке вставок;
* **`details` проходит через `jsonb`**: порядок ключей не сохраняется, целые числа возвращаются
  целыми. Пересчёт хэша по прочитанной строке обязан совпасть с тем, что отхэшировало приложение
  (`ADR-025` п. 2), иначе разбор цепочки был бы непрерывным потоком ложных находок;
* **адрес возвращается объектом `ipaddress`**, а не строкой, которую подавали: канонический текст
  обязан совпасть с записанным (замер `ADR-009`, та же форма, что и в списке сеансов);
* **развилку цепочки закрывает база** (`ix_audit_log_hash_prev_linked`, ревизия `0007`): вторая
  строка на того же предка отклоняется `23505` — и для роли-владельца схемы тоже, в отличие от
  append-only прав из `deploy/postgres/roles.sql`, которые у владельца не действуют. Развилка —
  это две строки с **одним и тем же** `hash_prev`: строка с `NULL` и её единственный потомок
  конфликтом не являются (замер прогона CI `45163930282`: первая версия проверки вставляла
  законную пару «родитель → потомок» и, разумеется, не получала отказа);
* **обход через `ON CONFLICT DO NOTHING` не создаёт строку** — поэтому он на журнале запрещён
  (`ADR-025` п. 4): потерянное событие разбор показывает как `broken_link`, то есть как подделку;
* **ручную правку и вырез строки разбор находит** — вторая половина `AC-identity-04` («изменённая
  вручную копия дампа → найден разрыв»). Правим и вырезаем мы именно ролью-владельцем: у роли
  приложения `UPDATE`/`DELETE` на журнале отозваны (первая половина той же приёмки — шаг
  «append-only права роли приложения», `tests/integration/test_postgres_roles.py`).

Ещё одно требование к этим проверкам, тоже из замера (`CI 45163930282`): **читать после правки
обязано другое соединение**. Сессия, которая сама выполнила `UPDATE`, возвращает из identity map
прежние атрибуты, и разбор по ней показал бы целую цепочку на испорченной строке. Так же читает и
`make audit-verify`: отдельным прогоном, поверх зафиксированного состояния.

Запуск: `TBOT_DB_URL` на базу, развёрнутую до `upgrade head` (так и стоит в job'е `миграции`).
Без переменной группа пропускается целиком (на dev-машине базы нет), при заданной, но недоступной
базе — падает, а не пропускается. Строки этого файла удаляются уборкой по маркеру: право `DELETE`
на журнале у приложения отозвано, поэтому уборка возможна только потому, что тест идёт ролью
владельца схемы (`ADR-018`) — это же и есть причина, по которой разбор цепочки вообще нужен.
"""

from __future__ import annotations

import os
import uuid
from collections.abc import Iterator
from datetime import datetime
from typing import Any, Final

import pytest
from sqlalchemy import Connection, Engine, create_engine, delete, select, text
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session, sessionmaker

from packages.common.clock import utc_now
from packages.common.db import sqlalchemy_url
from packages.identity.audit import (
    AuditRecord,
    build_audit_entry,
    canonical_ip,
    make_record,
    record_of_entry,
    verify_chain,
)
from packages.storage.models import AuditLogEntry

# Читается до аутофикстуры `clean_tbot_env` (она убирает TBOT_* внутри теста): на уровне модуля
# решается, идти ли в группу целиком или пропустить её.
_DB_URL = os.environ.get("TBOT_DB_URL", "")

_UNIQUE_VIOLATION: Final = "23505"
_FORK_INDEX: Final = "ix_audit_log_hash_prev_linked"
#: Маркер строк этого файла: `entity_id` — текст (§4.1), и по нему строки убираются уборкой.
_MARKER_PREFIX: Final = "t109r1"

pytestmark = pytest.mark.skipif(
    not _DB_URL,
    reason="нет TBOT_DB_URL: нужны живой PostgreSQL (группа исполняется в CI job `migrations`)",
)


@pytest.fixture(scope="module")
def engine() -> Iterator[Engine]:
    """Движок владельца схемы: адрес обязан быть прогнан через `sqlalchemy_url` (`ADR-018`).

    В job'е `миграции` переменная стоит в прямой форме `postgresql://…`, а SQLAlchemy искала бы
    `psycopg2` — драйвер в проекте один, psycopg3 (`packages/common/db.py`).
    """
    created = create_engine(sqlalchemy_url(_DB_URL), pool_pre_ping=True)
    yield created
    created.dispose()


@pytest.fixture
def session(engine: Engine) -> Iterator[Session]:
    """Сессия владельца схемы и уборка строк журнала по маркеру после теста.

    Уборка обязана быть явной: права приложения на журнале — только `SELECT`+`INSERT`, поэтому
    «само рассосётся» для этих строк не наступает, а повторный прогон job'а по той же базе увидел
    бы чужие строки в цепочке.
    """
    opened = sessionmaker(bind=engine, expire_on_commit=False)()
    yield opened
    # Откат перед чисткой: если проверка упала ассертом внутри блока `pytest.raises(IntegrityError)`,
    # транзакция сессии остаётся в состоянии «откатить», и финализор выдал бы
    # PendingRollbackError вместо настоящего сообщения об ошибке (замер `CI 45165930936`:
    # так «1 failed» превратилось в «1 failed + 1 error»).
    opened.rollback()
    opened.execute(delete(AuditLogEntry).where(AuditLogEntry.entity_id.like(f"{_MARKER_PREFIX}%")))
    opened.commit()
    opened.close()


def _marker() -> str:
    return f"{_MARKER_PREFIX}-{uuid.uuid4().hex[:10]}"


def _insert(
    session: Session,
    *,
    marker: str,
    index: int,
    hash_prev: str | None,
    action: str = "session.login",
    at: datetime | None = None,
    details: dict[str, Any] | None = None,
    ip: str | None = None,
) -> AuditLogEntry:
    """Вставить запись журнала по протоколу добавления: хэш посчитан, `id` выдаёт база.

    `hash_prev` передаётся явно (а не читается «хвостом» таблицы): тест строит свою ветку, и
    чужие строки других шагов job'а на неё влиять не должны. Протокол с блокировкой хвоста
    (`ADR-025` п. 6) — часть слоя доступа, срез `R2` этой же задачи. `flush()` — внутри
    помощника: отказ уникальности обязан приходить на строке вызова, а не отдельным оператором
    внутри `pytest.raises` (`PT012`).
    """
    record = make_record(
        action=action,
        at=at if at is not None else utc_now(),
        entity="session",
        entity_id=f"{marker}-{index}",
        details=details,
        ip=ip,
        hash_prev=hash_prev,
    )
    entry = build_audit_entry(record)
    session.add(entry)
    session.flush()
    return entry


def _build_chain(session: Session, marker: str, count: int = 3) -> list[AuditLogEntry]:
    entries: list[AuditLogEntry] = []
    previous: str | None = None
    for index in range(1, count + 1):
        entry = _insert(
            session,
            marker=marker,
            index=index,
            hash_prev=previous,
            details={"номер": index, "вложенно": {"б": 1, "а": [1, 2]}},
            ip="::ffff:127.0.0.1" if index == 1 else "2001:0DB8::7",
        )
        entries.append(entry)
        previous = entry.hash
    session.commit()
    return entries


def _read(session: Session, marker: str) -> list[AuditLogEntry]:
    """Прочитать строки маркера по `id` — так же, как их читает `make audit-verify`."""
    statement = (
        select(AuditLogEntry)
        .where(AuditLogEntry.entity_id.like(f"{marker}%"))
        .order_by(AuditLogEntry.id)
    )
    return list(session.scalars(statement).all())


def _read_fresh(bind: Engine | Connection, marker: str) -> list[AuditLogEntry]:
    """Прочитать строки маркера новым соединением.

    Нужно после прямой правки или выреза: та же сессия вернула бы из identity map прежние
    атрибуты, и разбор показал бы целую цепочку на испорченной строке (замер `CI 45163930282`).
    """
    fresh = sessionmaker(bind=bind, expire_on_commit=False)()
    try:
        return _read(fresh, marker)
    finally:
        fresh.close()


# ─── пересчёт по живой таблице ──────────────────────────────────────────────────────────────


def test_цепочка_прочитанная_из_базы_пересчитывается_без_находок(session: Session) -> None:
    """Главное утверждение среза: то, что отхэшировало приложение, совпадает с тем, что вернула база.

    Расхождение здесь означало бы, что разбор цепочки на площадке краснеет сам по себе, и
    настоящую правку строки на этом шуме не найти.
    """
    marker = _marker()
    _build_chain(session, marker, count=4)

    rows = _read(session, marker)
    assert len(rows) == 4, "уборка или фильтр маркером работают неверно"
    assert [row.id for row in rows] == sorted(
        row.id for row in rows
    ), "`id` обязан выдаваться базой по порядку вставок: по нему читают хронологию журнала"
    assert all(
        row.hash_prev is not None for row in rows[1:]
    ), "связь цепочки обязана быть заполнена"

    stored = [record_of_entry(row) for row in rows]
    for row, item in zip(rows, stored, strict=True):
        assert item.stored_hash == row.hash
        recomputed = item.record.content_hash()
        assert (
            recomputed == row.hash
        ), f"строка {row.id}: пересчёт не совпал с колонкой hash — разбор дал бы ложный разрыв"

    report = verify_chain(stored, expect_genesis=False)
    assert report.intact, report.summary()
    assert report.rows == 4


def test_значения_после_чтения_из_базы_остаются_каноничными(session: Session) -> None:
    """`jsonb` не сохраняет порядок ключей, а `INET` читается объектом `ipaddress`.

    Проверка держит три факта разом: адрес возвращается в канонической форме (и IPv4-mapped
    форма, поданная приложением, не должна «всплыть» обратно), микросекунды момента
    сохраняются ровно те, что отхэшировали, и канонический JSON `details` не зависит от того,
    в каком порядке ключи вернулись из базы.
    """
    marker = _marker()
    at = utc_now().replace(microsecond=654321)
    entry = _insert(
        session,
        marker=marker,
        index=1,
        hash_prev=None,
        at=at,
        details={"б": 1, "а": {"y": 2, "x": [1, 2], "нуль": None}, "текст": "данные"},
        ip="::ffff:127.0.0.1",
    )
    session.commit()
    stored_hash = entry.hash

    fresh = _read_fresh(session.get_bind(), marker)
    assert len(fresh) == 1
    row = fresh[0]
    assert row.at == at, "колонка `timestamptz` вернула другой момент — хэш не совпадёт"
    assert str(row.ip) == "127.0.0.1", (
        "колонка INET вернула не канонический текст: IPv4-mapped форма при записи обязана "
        "приводиться к IPv4 (`ADR-025` п. 2)"
    )
    # psycopg3 читает `INET` объектом `ipaddress`, а не строкой, которую подавали (замер
    # `ADR-009`): нормализация обязана принимать и его, и текст, иначе пересчёт хэша разошёлся
    # бы с записанным значением ровно на форме адреса.
    assert canonical_ip(row.ip) == "127.0.0.1"
    # Порядок ключей из `jsonb` произволен: канонический вывод обязан его не различать.
    item = record_of_entry(row)
    assert (
        item.record.canonical_json()
        == make_record(
            action="session.login",
            at=at,
            entity="session",
            entity_id=row.entity_id,
            details={"а": {"нуль": None, "x": [1, 2], "y": 2}, "б": 1, "текст": "данные"},
            ip="127.0.0.1",
        ).canonical_json()
    )
    assert item.record.content_hash() == stored_hash


# ─── развилку держит база ───────────────────────────────────────────────────────────────────


def test_второй_записи_на_того_же_предка_база_отклоняет(session: Session) -> None:
    """`ix_audit_log_hash_prev_linked` (ревизия `0007`) — страж, а не договорённость.

    Развилка — это две строки с одним и тем же `hash_prev`, поэтому проверка строит родителя, его
    законного потомка и **вторую** попытку того же потомка. Без индекса два процесса, прочитавшие
    один хвост, молча открыли бы две ветки: развилка не видна ни в одной колонке, и «разрыв
    цепочки» перестал бы быть признаком правки.

    Отклонение ждёт именно `23505` (нарушение уникальности), а не «какую-нибудь ошибку»: по коду
    слой доступа в срезе `R2` отличит конфликт цепочки от прочего и решит, повторять ли
    транзакцию. Индекс действует и для роли-владельца схемы — в отличие от append-only прав,
    которые у владельца не работают (`deploy/postgres/roles.sql`, п. 2.1). Поэтому страж выбран
    индексом, а не только правами.
    """
    marker = _marker()
    parent = _insert(session, marker=marker, index=1, hash_prev=None)
    parent_hash = parent.hash
    _insert(session, marker=marker, index=2, hash_prev=parent_hash)
    session.commit()

    with pytest.raises(IntegrityError) as captured:
        _insert(session, marker=marker, index=3, hash_prev=parent_hash)
    error = captured.value
    # Код состояния берём из атрибута `sqlstate`, а не из текста: psycopg3 поднимает
    # `psycopg.errors.UniqueViolation`, и в его сообщении кода `23505` нет (замер
    # `CI 45165930936`: проверка искала подстроку в тексте и не находила, хотя отказ был ровно
    # тот, что нужен).
    sqlstate = str(getattr(error.orig, "sqlstate", ""))
    assert (
        sqlstate == _UNIQUE_VIOLATION
    ), f"ожидался отказ уникальности {_UNIQUE_VIOLATION}, получено: {sqlstate!r} ({error.orig!r})"
    assert _FORK_INDEX in str(
        error
    ), f"отклонить обязан именно индекс {_FORK_INDEX}, а не случайное ограничение: {error}"
    session.rollback()

    survivors = _read_fresh(session.get_bind(), marker)
    assert len(survivors) == 2, "неудачная вставка оставила строку — транзакт откатился не целиком"
    report = verify_chain([record_of_entry(row) for row in survivors], expect_genesis=False)
    assert report.intact, f"отклонённая развилка попалась в разбор: {report.summary()}"
    assert survivors[1].hash_prev == parent_hash


def test_повтор_одной_и_той_же_записи_база_тоже_отклоняет(session: Session) -> None:
    """Повторная вставка того же события (retry «не думая») — та же развилка и тот же отказ.

    Самый дешёвый способ сбить пересчёт по количеству строк — записать событие дважды, например
    после таймаута соединения. Пока вторая строка ссылается на того же предка, индекс не даёт ни
    развилки, ни дубля, поэтому повтор обязан кончиться отказом, а не «ещё одной строкой журнала».
    """
    marker = _marker()
    parent = _insert(session, marker=marker, index=1, hash_prev=None)
    parent_hash = parent.hash
    _insert(
        session,
        marker=marker,
        index=2,
        hash_prev=parent_hash,
        action="backup_code.spent",
        details={"кодов_осталось": 9},
    )
    session.commit()

    with pytest.raises(IntegrityError) as captured:
        _insert(
            session,
            marker=marker,
            index=3,
            hash_prev=parent_hash,
            action="backup_code.spent",
            details={"кодов_осталось": 9},
        )
    assert _FORK_INDEX in str(captured.value)
    session.rollback()
    assert len(_read_fresh(session.get_bind(), marker)) == 2


def test_обход_через_on_conflict_do_nothing_не_создаёт_строку(session: Session) -> None:
    """Наивный «upsert» журнал не спасает, а молча теряет запись — поэтому он запрещён.

    `ADR-025` п. 4 запрещает `ON CONFLICT DO NOTHING` на журнале: без индекса (`0007`) такая
    конструкция не infer-ится ни на какой объект и не работала бы вовсе, а с индексом — тихо
    выбрасывает строку, и потерянное событие становится дырой, которую разбор показывает как
    `broken_link`, то есть как подделку содержимого. Проверка фиксирует обе половинки: вывод
    `ON CONFLICT (hash_prev) WHERE hash_prev IS NOT NULL` опирается именно на частичный индекс
    `0007`, и строка не появляется — значит слой доступа (`R2`) обязан смотреть на число
    затронутых строк, а не на отсутствие ошибки.

    Порядок строк обязателен: конфликт бывает только у предка, у которого **уже есть** потомок.
    Первая версия проверки вставляла одного родителя и получала `rowcount == 1` — не потому, что
    индекс не работает, а потому, что конфликтовать было не с чем (замер `CI 45165930936`).
    """
    marker = _marker()
    parent = _insert(session, marker=marker, index=1, hash_prev=None)
    _insert(session, marker=marker, index=2, hash_prev=parent.hash)
    session.commit()
    record = make_record(
        action="session.login",
        at=utc_now(),
        entity="session",
        entity_id=f"{marker}-obhod",
        hash_prev=parent.hash,
    )

    # `session.connection()` вместо `session.execute()`: описания SQLAlchemy возвращают
    # `CursorResult` только у соединения, а нам нужен `rowcount` — по нему слой доступа (`R2`)
    # обязан отличать «конфликт цепочки подавлен индексом» от «запись вставлена».
    result = session.connection().execute(
        text(
            "INSERT INTO audit_log (at, action, actor, entity, entity_id, details, ip, hash, "
            "hash_prev, request_id) VALUES (:at, :action, NULL, :entity, :entity_id, NULL, NULL, "
            ":hash, :hash_prev, NULL) "
            "ON CONFLICT (hash_prev) WHERE hash_prev IS NOT NULL DO NOTHING"
        ),
        {
            "at": record.at,
            "action": record.action,
            "entity": record.entity,
            "entity_id": record.entity_id,
            "hash": record.content_hash(),
            "hash_prev": record.hash_prev,
        },
    )
    session.commit()

    assert result.rowcount == 0, (
        "вставка на занятого предка обязана быть подавлена индексом "
        f"{_FORK_INDEX}; прошла строка — значит ON CONFLICT вывел бы не тот объект"
    )
    survivors = _read_fresh(session.get_bind(), marker)
    assert len(survivors) == 2, (
        "`DO NOTHING` оставил лишнюю строку или съел законную — ожидались родитель и его "
        f"потомок, найдено {len(survivors)}"
    )
    assert verify_chain(
        [record_of_entry(row) for row in survivors], expect_genesis=False
    ).intact, "молча потерянная строка уже сломала цепочку"


# ─── ручная правка и вырез ──────────────────────────────────────────────────────────────────


def test_правка_строки_ролью_владельца_находится_пересчётом(session: Session) -> None:
    """Вторая половина `AC-identity-04`: изменённую вручную строку обязано найти.

    Правим прямым `UPDATE` ролью-владельцем: у роли приложения такого права нет
    (`REQ-identity-04`), значит остаётся ровно путь «человек с правами базы» — именно он и
    моделируется. Колонку `hash` при этом не трогают: пересчитать новый хэш подделыватель тоже
    не обязан. Чтение — новым соединением (`_read_fresh`): та же сессия вернула бы из identity
    map прежние атрибуты, и проверка прошла бы на целой цепочке, ничего не проверив.
    """
    marker = _marker()
    rows = _build_chain(session, marker, count=3)
    target_id = rows[1].id
    assert target_id is not None

    session.execute(
        text("UPDATE audit_log SET action = 'session.logout', actor = NULL WHERE id = :id"),
        {"id": target_id},
    )
    session.commit()

    after = _read_fresh(session.get_bind(), marker)
    assert [row.action for row in after][
        1
    ] == "session.logout", "правка не дошла до базы — проверять было нечего"
    report = verify_chain([record_of_entry(row) for row in after], expect_genesis=False)
    kinds = {issue.kind for issue in report.issues}
    assert kinds == {"content_mismatch"}, report.summary()
    issue = report.issues[0]
    assert issue.row_id == target_id
    assert "цепочка нарушена" in report.summary()


def test_вырез_строки_ролью_владельца_находится_разрывом(session: Session) -> None:
    """Вырезанная строка ломает связь следующей: `broken_link`, а не «всё стало короче».

    Отдельный код важен: «журнал стал короче на одну строку» и «строку вырезали из середины» —
    разные события для разбора инцидента (ср. `docs/HANDOFF.md §1.60` п. 7: инициатора отзыва
    строки 08:19:08 UTC восстановить нечем, и «недостающая строка» — ровно то, что журнал обязан
    показать). Чтение — новым соединением, как в проверке выше.
    """
    marker = _marker()
    rows = _build_chain(session, marker, count=4)
    removed = rows[1].id
    assert removed is not None
    session.execute(text("DELETE FROM audit_log WHERE id = :id"), {"id": removed})
    session.commit()

    after = _read_fresh(session.get_bind(), marker)
    assert len(after) == 3
    report = verify_chain([record_of_entry(row) for row in after], expect_genesis=False)
    kinds = {issue.kind for issue in report.issues}
    assert kinds == {"broken_link"}, report.summary()
    assert report.issues[0].row_id == rows[2].id
    assert report.issues[0].previous_id == rows[0].id


def test_цепочку_читают_по_другому_соединению_без_пересчёта_заново(session: Session) -> None:
    """Разбор читает зафиксированное состояние, а не identity map текущего запроса.

    Тот же приём, что у живых проверок сеансов: «виден след» означает «видно новому
    соединению», иначе `audit-verify` показывал бы состояние незакрытой транзакции.
    """
    marker = _marker()
    _build_chain(session, marker, count=3)

    first_view = _read(session, marker)
    second_view = _read_fresh(session.get_bind(), marker)
    assert [row.id for row in first_view] == [row.id for row in second_view]
    assert [row.hash for row in first_view] == [row.hash for row in second_view]
    report = verify_chain([record_of_entry(row) for row in second_view], expect_genesis=False)
    assert report.intact, report.summary()


def test_материал_хэша_живёт_в_колонках_а_не_в_приложении(session: Session) -> None:
    """Значения колонок обязаны полностью воспроизводить материал хэша.

    Чужой читатель (разбор по `psql`, восстановление дампа) пересчитывает хэш только по
    колонкам: если бы что-то существенное жило вне таблицы — порядок ключей, форма адреса,
    часовой пояс, — цепочку нельзя было бы проверить вне приложения. Проверка строит запись
    «вручную» из прочитанных колонок и сравнивает результат с колонкой `hash`.
    """
    marker = _marker()
    entry = _insert(
        session,
        marker=marker,
        index=1,
        hash_prev=None,
        action="backup_code.spent",
        details={"codes_left": 9, "причина": "recovery", "пусто": None},
        ip="2001:0db8::07",
    )
    session.commit()

    row = _read_fresh(session.get_bind(), marker)[0]
    manual = AuditRecord(
        at=row.at,
        action=row.action,
        actor=row.actor,
        entity=row.entity,
        entity_id=row.entity_id,
        details=row.details,
        ip=str(row.ip),
        request_id=row.request_id,
        hash_prev=row.hash_prev,
    )
    assert manual.content_hash() == row.hash == entry.hash
